// migrate.js
const fs = require('fs');
const path = require('path');

// Directory containing migration SQL files
class DatabaseMigration {
  constructor(migrationDir = './migrations') {
    this.migrationDir = path.resolve(migrationDir);
  }

  // Read all migration files and sort them
  getMigrationFiles() {
    try {
      const files = fs.readdirSync(this.migrationDir);
      // Filter only .sql files and sort them alphabetically
      return files
        .filter(file => path.extname(file).toLowerCase() === '.sql')
        .sort()
        .map(file => path.join(this.migrationDir, file));
    } catch (err) {
      if (err.code === 'ENOENT') {
        console.error(`Migration directory not found: ${this.migrationDir}`);
      } else {
        console.error('Error reading migration directory:', err.message);
      }
      return [];
    }
  }

  // Run the migration process
  run() {
    console.log('Starting database migration...');
    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration(s):`);
    migrationFiles.forEach(file => {
      console.log(`Applying migration: ${path.basename(file)}`);
      // In a real scenario, you'd execute the SQL file here
    });

    console.log('Migration completed.');
  }
}

// Execute migration
if (require.main === module) {
  const migrator = new DatabaseMigration();
  migrator.run();
}

module.exports = DatabaseMigration;

