const fs = require('fs');
const path = require('path');

function config(options = {}) {
  const filePath = options.path || '.env';

  try {
    const contents = fs.readFileSync(filePath, 'utf8');
    const lines = contents.split('\n');

    lines.forEach(line => {
      // Skip empty lines and comments
      if (line.trim() === '' || line.trim().startsWith('#')) {
        return;
      }

      // Parse key-value pair
      const [key, ...valueParts] = line.split('=');
      const value = valueParts.join('='); // Handle = in value

      // Remove quotes and whitespace
      const cleanedValue = value.trim().replace(/^['"]|['"]$/g, '');

      // Set in process.env if not already set
      if (!(key.trim() in process.env)) {
        process.env[key.trim()] = cleanedValue;
      }
    });

    return { parsed: true };
  } catch (error) {
    if (error.code !== 'ENOENT') {
      console.error(`Error loading environment variables from ${filePath}:`, error.message);
    }
    return { error };
  }
}

module.exports = { config };

