function postToAuditService(data) {
  return new Promise((resolve, reject) => {
    const client = data.url.startsWith('https:') ? https : http;
    const auditUrl = new URL(data.url);

    const options = {
      hostname: auditUrl.hostname,
      port: auditUrl.port,
      path: auditUrl.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
    };

    const req = client.request(options, (res) => {
      let responseBody = '';
      res.on('data', chunk => { responseBody += chunk; });
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve({ success: true, statusCode: res.statusCode, response: responseBody });
        } else {
          reject(new Error(`Audit service returned error: ${res.statusCode} ${responseBody}`));
        }
      });
    });

    req.on('error', reject);
    req.write(JSON.stringify(data.body));
    req.end();
  });
}

