// migrate.js
const fs = require('fs');
const path = require('path');

// Directory containing SQL migration files
class MigrationRunner {
  constructor(migrationsDir = './migrations') {
    this.migrationsDir = path.resolve(migrationsDir);
  }

  // Read all SQL files from the migrations directory and sort them
  getMigrationFiles() {
    try {
      const files = fs.readdirSync(this.migrationsDir);
      // Filter for .sql files and sort them alphabetically
      return files
        .filter(file => file.endsWith('.sql'))
        .sort()
        .map(file => path.join(this.migrationsDir, file));
    } catch (err) {
      if (err.code === 'ENOENT') {
        console.error(`Migrations directory not found: ${this.migrationsDir}`);
      } else {
        console.error('Error reading migrations directory:', err.message);
      }
      return [];
    }
  }

  // Simulate applying migrations (just logs the filename)
  run() {
    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migrations to apply.');
      return;
    }

    console.log('Applying migrations:');
    migrationFiles.forEach(file => {
      console.log(`- Applying: ${path.basename(file)}`);
    });
  }
}

// Run the migration
if (require.main === module) {
  const runner = new MigrationRunner();
  runner.run();
}

module.exports = MigrationRunner;

