constructor(migrationsDir = './migrations') {
  this.migrationsDir = path.resolve(migrationsDir);

  // Load all environment variables from .env.test
  this.envVars = {};
  try {
    const envContent = fs.readFileSync('.env.test', 'utf8');
    envContent.split('\n').forEach(line => {
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        this.envVars[match[1].trim()] = match[2].trim();
      }
    });
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error('.env.test file not found');
    }
    throw err;
  }

  this.databaseUrl = this.envVars.DATABASE_URL;
  if (!this.databaseUrl) {
    throw new Error('DATABASE_URL not found in .env.test');
  }
}

